def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_me, last_opp = history[-1]

    # Endgame exploitation: if opponent highly cooperative, defect late.
    if n >= 93:
        if opp_d <= 3:
            return 'D'
        return 'D' if last_opp == 'D' else 'C'

    # Opponent never defected: cooperate, but sneak one late defect.
    if opp_d == 0:
        if n >= 90:
            return 'D'
        return 'C'

    # Opponent never cooperated: always defect.
    if opp_c == 0:
        return 'D'

    # Recent windows
    w = history[-12:]
    r_opp_c = sum(1 for _, o in w if o == 'C')
    r_len = len(w)

    # If opponent recently very cooperative, cooperate (but probe rarely)
    if r_len >= 8 and r_opp_c >= r_len - 1:
        if n >= 25 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # If opponent recently mostly defective, defect
    if r_len >= 6 and r_opp_c <= 1:
        return 'D'

    # Track runs of opponent defection
    if last_opp == 'D':
        run = 0
        for o in reversed(opp):
            if o == 'D':
                run += 1
            else:
                break
        if run >= 2:
            return 'D'
        # Single recent defection: forgive if opponent mostly cooperative
        if opp_c * 2 >= n and n >= 6:
            # But if we defected last round too, avoid losing more
            if last_me == 'D':
                if rng.random() < 0.25:
                    return 'C'
                return 'D'
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If they've been sufficiently cooperative overall, cooperate.
    if opp_c * 3 >= n * 2:
        return 'C'

    # Mixed opponent: cooperate but retaliate quickly to recent defections.
    if r_len >= 4:
        recent_d = sum(1 for _, o in history[-4:] if o == 'D')
        if recent_d >= 2:
            return 'D'
    return 'C'
